export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const t = time;
  const height = launchSpeed * t - 0.5 * gravity * t * t;
  const velocity = launchSpeed - gravity * t;

  const maxH = (launchSpeed * launchSpeed) / (2 * gravity);
  const maxT = launchSpeed / gravity;
  const clampedH = Math.max(0, height);

  const ballY = 320 - clampedH * 60;
  const ballX = 200;

  const objects = [];

  objects.push(sdk.panel({ id: 'lane.toss', x: 40, y: 40, w: 560, h: 350, title: 'Vertical Toss', state: t === 0 ? 'Paused at launch' : (Math.abs(velocity) < 0.1 ? 'At the top' : (velocity > 0 ? 'Moving up' : 'Moving down')) }));

  objects.push(sdk.axis('axis.height', { x: 100, y: 320, length: 240, orientation: 'y', min: 0, max: 2.5, ticks: [0, 0.5, 1.0, 1.5, 2.0, 2.5], label: 'Height', unit: 'm' }));

  objects.push(sdk.groundMark('ground.launch', ballX, 320, 60, 'Launch'));

  objects.push(sdk.circle('ball.toss', ballX, ballY, 24, { role: 'output' }));

  if (Math.abs(velocity) > 0.05) {
    objects.push(sdk.vector('vec.v', { x: ballX + 20, y: ballY }, { value: velocity, direction: 'up' }, { scale: 10, minLength: 12, label: 'v' }));
  }

  objects.push(sdk.vector('vec.a', { x: ballX - 25, y: ballY }, { value: -gravity, direction: 'up' }, { scale: 5, minLength: 12, label: 'a' }));

  let motionText = 'Moving up';
  if (Math.abs(velocity) < 0.05) {
    motionText = 'Still for an instant';
  } else if (velocity < 0) {
    motionText = 'Moving down';
  }

  objects.push(sdk.callout(ballX + 45, ballY - 20, [motionText, 'Gravity pulls down'], { id: 'callout.toss' }));

  let motionStateVal = 'Rising';
  if (Math.abs(velocity) < 0.05) {
    motionStateVal = 'At top';
  } else if (velocity < 0) {
    motionStateVal = 'Falling';
  }

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: 'motionState', value: motionStateVal },
        { id: 'gravityState', value: 'Pulling down' }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime: maxT,
      apexHeight: maxH,
      velocity,
      height: clampedH
    }
  };
}
